# Deduplicate internally and filter against existing
seen_slugs = set()
unique_candidates = []

for c in CANDIDATES:
    slug = slugify(c["title"])
    if slug in existing_slugs or slug in seen_slugs:
        continue
    seen_slugs.add(slug)
    unique_candidates.append(c)

print(f"Total existing movies: {len(existing_titles)}")
print(f"Total new valid unique candidates in this batch: {len(unique_candidates)}")
print(f"Grand Total if all added: {len(existing_titles) + len(unique_candidates)}")

with open('candidates_batch.json', 'w', encoding='utf-8') as f:
    json.dump(unique_candidates, f, indent=2)
